    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

# Collect mapping line_color -> fill for all demos
pairs = {}
for nm in sorted(G):
    if 'input' in nm:
        k = nm.replace(' input','')
        i,o=G[nm]; R,C=len(i),len(i[0])
        sr=[r for r in range(R) if len(set(i[r]))==1]
        sc=[c for c in range(C) if len({i[rr][c] for rr in range(R)})==1]
        lc = {i[rr][cc] for rr in sr} | {i[0][cc] for cc in sc}
        fill = {o[r][c] for r in sr for c in range(C)} | {o[r][c] for r in range(R) for c in sc}
        pairs[k]=(sorted(lc)[0], sorted(fill)[0], i, o, sr, sc)
for k,(lc,f,r,i,o,sr,sc) in pairs.items():
    print(k,'linecolor',lc,'fill',f,'nrowsolid',len(sr),'ncolsolid',len(sc))

